function setPace(value){pace=RouteePace.profile(value);$('pace').value=pace.speed;$('pace').setAttribute('aria-valuetext',pace.mode+' · '+Math.round((pace.speed-RouteePace.min)/(RouteePace.max-RouteePace.min)*100)+'%');$('pace').style.setProperty('--pace-fill',((pace.speed-RouteePace.min)/(RouteePace.max-RouteePace.min)*100)+'%');$('walkPace').setAttribute('aria-pressed',String(pace.mode==='걷기'));$('runPace').setAttribute('aria-pressed',String(pace.mode==='뛰기'));$('world').dataset.pace=pace.mode;}
$('pace').addEventListener('input',e=>setPace(e.target.value));$('walkPace').onclick=()=>setPace(RouteePace.walk);$('runPace').onclick=()=>setPace(RouteePace.run);setPace(RouteePace.walk);

$('continueTrail').onclick=()=>{if(state!=='summit')return;clearTimeout(arrivalTimer);$('continuePanel').hidden=true;$('summit').classList.remove('show');document.body.classList.remove('summit-landed');summitTarget+=world.summit;arrived=false;state='run';autoBranch=null;targetHeading=travelHeading=gestureHeading=0;$('world').setAttribute('aria-label','다음 정상으로 이어지는 산길. 클릭하거나 방향키로 자유롭게 이동하세요.');$('instruction').textContent='다음 여정도 나만의 루트로. 숲과 능선이 다시 이어져요.';toast('산행을 이어갑니다 · 거리와 사진은 그대로 남아요.');$('world').focus({preventScroll:true})};$('endTrail').onclick=()=>$('finish').click();
